"""
Shared fakes for fact-checker tests. Not a test module itself (no
`test_` prefix), so pytest won't try to collect it.
"""

import hashlib

import requests

from src.services.fact_checker.ranking.ranking_retrieval import RankingResult
from src.services.fact_checker.retrieval.evidence_retriever import RetrievalResult
from src.services.fact_checker.retrieval.query_builder import PlannedQuery, QueryKind
from src.services.scraper.fetcher import FetchedPage
from src.services.search import SearchUnavailableError


class FakeEmbeddingService:
    """
    Deterministic stand-in for EmbeddingService. Mirrors its exact
    contract: encode() returns a vector, similarity() is a raw dot
    product over two vectors (real EmbeddingService.encode() already
    normalizes, so vectors here are pre-normalized too).

    Pass `vectors={"some text": [...]}` to pin specific texts to
    specific vectors (e.g. to control duplicate/relatedness outcomes);
    unmapped text falls back to a deterministic hash-derived vector so
    unrelated strings behave as roughly unrelated.
    """

    DIM = 8

    def __init__(self, vectors: dict[str, list[float]] | None = None):
        self._vectors = vectors or {}

    def encode(self, text: str) -> list[float]:
        if text in self._vectors:
            return list(self._vectors[text])
        return self._hash_vector(text)

    def encode_many(self, texts):
        return [self.encode(text) for text in texts]

    def similarity(self, embedding1, embedding2) -> float:
        return float(sum(a * b for a, b in zip(embedding1, embedding2)))

    def _hash_vector(self, text: str) -> list[float]:
        digest = hashlib.sha256(text.encode()).digest()
        raw = [b / 255.0 for b in digest[: self.DIM]]
        norm = sum(v * v for v in raw) ** 0.5 or 1.0
        return [v / norm for v in raw]


class FakeSearxngClient:
    """
    `results` answers every query - unless `results_by_term` is given,
    in which case a query containing one of its terms (case-insensitive,
    first match wins) gets that term's results instead, and `results`
    only answers the rest.

    The routing exists for end-to-end runs, where the claims come out of
    real extraction and their queries are not known in advance: a figure
    the anchor query quotes verbatim ("87%") is enough to give one claim
    evidence and leave the others with none, in the same run.
    """

    def __init__(
        self,
        results: list[dict] | None = None,
        unavailable: bool = False,
        results_by_term: dict[str, list[dict]] | None = None,
    ):
        self.results = results or []
        # Every query fails, the way they did during the 2026-09-25 outage.
        self.unavailable = unavailable
        self.results_by_term = results_by_term or {}
        self.queries: list[str] = []
        self.languages: list[str | None] = []

    def search(
        self,
        query: str,
        max_results: int | None = None,
        language: str | None = None,
    ) -> list[dict]:
        self.queries.append(query)
        self.languages.append(language)
        if self.unavailable:
            raise SearchUnavailableError("no results; engines down: brave (too many requests)")
        results = next(
            (
                hits
                for term, hits in self.results_by_term.items()
                if term.lower() in query.lower()
            ),
            self.results,
        )
        limit = max_results or len(results)
        return results[:limit]


class FakeFetcher:
    """
    The network underneath the extraction cascade: `pages` maps a URL to
    the HTML its server would return. Stands in for `Fetcher`, so the
    real strategies (trafilatura, BeautifulSoup) parse real HTML and only
    the request itself is fake.

    Any URL not in `pages` answers 404, the way a missing page does - so
    a test that forgot a page sees an ordinary extraction failure, and
    can never fall through to a real request. `requested` records every
    URL asked for, in order.
    """

    def __init__(self, pages: dict[str, str] | None = None):
        self.pages = pages or {}
        self.requested: list[str] = []

    def get(self, url: str) -> FetchedPage:
        self.requested.append(url)
        if url not in self.pages:
            response = requests.Response()
            response.status_code = 404
            response.url = url
            raise requests.HTTPError(f"404 Client Error: Not Found for url: {url}", response=response)
        return FetchedPage(url=url, status=200, html=self.pages[url])


class FakeExtractorService:
    """
    news_by_url maps a URL to whatever `extract()` should return
    (a News instance, or None to simulate an extraction failure).
    Any URL not in the map also returns None. Passing an Exception
    instance simulates a scraping error.
    """

    def __init__(self, news_by_url: dict | None = None):
        self.news_by_url = news_by_url or {}

    def extract(self, source, url, thresholds=None, purpose="article"):
        result = self.news_by_url.get(url)
        if isinstance(result, Exception):
            raise result
        return result


class FakeLLMClient:
    """
    responses is a list of dicts (or None) consumed in order, one per
    complete_json() call - or a single dict/None reused for every call.
    """

    def __init__(self, responses=None):
        if isinstance(responses, list):
            self._responses = list(responses)
            self._single = None
        else:
            self._responses = None
            self._single = responses
        self.calls: list[tuple[str, str]] = []
        # What each call asked as its answer cap (the writer sets one).
        self.max_tokens: list[int | None] = []
        self.timeouts: list[float | None] = []

    def complete_json(
        self,
        system_prompt: str,
        user_prompt: str,
        max_retries: int = 1,
        max_tokens: int | None = None,
        timeout: float | None = None,
    ):
        self.calls.append((system_prompt, user_prompt))
        self.max_tokens.append(max_tokens)
        # What each call was given to answer in (a claim's deadline).
        self.timeouts.append(timeout)
        result = (
            (self._responses.pop(0) if self._responses else None)
            if self._responses is not None
            else self._single
        )
        if isinstance(result, Exception):
            raise result
        return result


class FakeSourceRepository:

    def __init__(self, sources: list | None = None):
        self._sources = sources or []

    def list(self):
        return self._sources

    def get(self, source_id: str):
        for source in self._sources:
            if source.id == source_id:
                return source
        return None


